mapper.select:
SELECT MAX(REPLACE(sub.stat_month, '-', ''))
FROM (
    SELECT stat_month FROM t_sr_strategy_period_summary_ap
    WHERE is_deleted = 0
    AND tab_type = #{tabType}
    AND city_id = #{cityId}
    AND county_id = #{countyId}
    UNION ALL
    SELECT stat_month FROM t_sr_strategy_period_summary_ctrl
    WHERE is_deleted = 0
    AND city_id = #{cityId}
    AND county_id = #{countyId}
) sub



        SELECT DATE_FORMAT(c.stat_month, '%Y%m') AS month,
               c.${metricColumn} AS value, c.${metricColumn}_qoq AS qoq
        FROM t_sr_channel_summary_ctrl c
        WHERE c.channel = #{channel} AND c.is_deleted = 0
          AND DATE_FORMAT(c.stat_month, '%Y-%m') <= #{statMonth}
        AND c.city_id = #{cityId}
        AND c.county_id = #{countyId}


        SELECT DATE_FORMAT(c.stat_month, '%Y%m') AS month,
               c.${metricColumn} AS value, c.${metricColumn}_qoq AS qoq
        FROM t_sr_channel_summary_ap c
        WHERE c.tab_type = #{tabType} AND c.channel = #{channel} AND c.is_deleted = 0
          AND DATE_FORMAT(c.stat_month, '%Y-%m') <= #{statMonth}
        AND c.city_id = #{cityId}
        AND c.county_id = #{countyId}

            AND c.strategy_class = #{strategyClass}

            AND c.strategy_class = '全部'



ORDER BY c.stat_month DESC LIMIT 12

choose.when:
SELECT c.channel AS channel, d.key_name AS channelName, c.strategy_count AS strategyCount, c.strategy_count_qoq AS strategyCountQoQ, c.consult_count AS consultCount, c.consult_count_qoq AS consultCountQoQ, c.retain_count AS retainCount, c.retain_count_qoq AS retainCountQoQ, c.retain_rate AS retainRate, c.retain_rate_qoq AS retainRateQoQ, c.dispatch_count AS dispatchCount, c.dispatch_count_qoq AS dispatchCountQoQ, c.success_count AS successCount, c.success_count_qoq AS successCountQoQ, c.success_rate AS successRate, c.success_rate_qoq AS successRateQoQ, c.income AS income, c.income_qoq AS incomeQoQ FROM t_sr_channel_summary_ctrl c LEFT JOIN t_sr_dim_channel d ON d.key_code = c.channel WHERE DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.strategy_class = #{strategyClass}
AND c.strategy_class = '全部'
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}
AND c.channel = #{channel}
AND c.channel !='全部'
ORDER BY
${orderByClause} c.strategy_count DESC

choose.otherwise:
SELECT c.channel AS channel, d.key_name AS channelName, c.strategy_count AS strategyCount, c.strategy_count_qoq AS strategyCountQoQ, c.original_cust AS originalCust, c.original_cust_qoq AS originalCustQoQ, c.push_count AS pushCount, c.push_count_qoq AS pushCountQoQ, c.usage_count AS usageCount, c.usage_count_qoq AS usageCountQoQ, c.usage_rate AS usageRate, c.usage_rate_qoq AS usageRateQoQ, c.reach_count AS reachCount, c.reach_count_qoq AS reachCountQoQ, c.target_conv_num AS targetConvNum, c.target_conv_num_qoq AS targetConvNumQoQ, c.target_conv_rate AS targetConvRate, c.target_conv_rate_qoq AS targetConvRateQoQ, c.product_conv_num AS productConvNum, c.product_conv_num_qoq AS productConvNumQoQ, c.product_conv_rate AS productConvRate, c.product_conv_rate_qoq AS productConvRateQoQ, c.expected_income AS expectedIncome, c.expected_income_qoq AS expectedIncomeQoQ, c.actual_income AS actualIncome, c.actual_income_qoq AS actualIncomeQoQ FROM t_sr_channel_summary_ap c LEFT JOIN t_sr_dim_channel d ON d.key_code = c.channel WHERE c.tab_type = #{tabType} AND DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.strategy_class = #{strategyClass}
AND c.strategy_class = '全部'
AND c.city_id = #{cityId}
AND c.channel = #{channel}
AND c.channel !='全部'
AND c.county_id = #{countyId}
ORDER BY
${orderByClause} c.strategy_count DESC

choose.when:
SELECT SUM(c.strategy_count) AS strategyCount, SUM(c.consult_count) AS consultCount, SUM(c.retain_count) AS retainCount, SUM(c.dispatch_count) AS dispatchCount, SUM(c.success_count) AS successCount, SUM(c.income) AS income FROM t_sr_channel_summary_ctrl c WHERE DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}

choose.otherwise:
SELECT SUM(c.strategy_count) AS strategyCount, SUM(c.original_cust) AS originalCust, SUM(c.push_count) AS pushCount, SUM(c.usage_count) AS usageCount, SUM(c.reach_count) AS reachCount, SUM(c.target_conv_num) AS targetConvNum, SUM(c.product_conv_num) AS productConvNum, SUM(c.expected_income) AS expectedIncome, SUM(c.actual_income) AS actualIncome FROM t_sr_channel_summary_ap c WHERE c.tab_type = #{tabType} AND DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.strategy_class = #{strategyClass}
AND c.strategy_class = '全部'
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}

mapper.sql:
WHERE s.tab_type = #{tabType}
  AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
  AND s.is_deleted = 0

    AND s.city_id = #{cityId}


    AND s.county_id = #{countyId}


    AND s.channel = #{channel}


    AND s.big_category = #{bigCategory}


    AND s.small_category = #{smallCategory}


    AND s.strategy_name LIKE CONCAT('%', #{strategyName}, '%')


    AND s.strategy_class = #{strategyClass}



    AND EXISTS (SELECT 1 FROM t_sr_strategy cg
        WHERE cg.strategy_code = s.strategy_id AND cg.tab_type = 'active'
          AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
          AND cg.customer_group = #{customerGroup})

WHERE DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
  AND s.is_deleted = 0

    AND s.city_id = #{cityId}


    AND s.county_id = #{countyId}


    AND s.channel = #{channel}


    AND s.big_category = #{bigCategory}


    AND s.small_category = #{smallCategory}


    AND s.strategy_name LIKE CONCAT('%', #{strategyName}, '%')



    AND EXISTS (SELECT 1 FROM t_sr_strategy product
        WHERE product.strategy_code = s.strategy_id AND product.tab_type = 'control'
          AND product.is_deleted = 0 AND product.product_name = #{productName})

choose.when:
SELECT m.stat_month AS month,
       m.capacity   AS capacity,
       m.qoq        AS qoq
FROM t_sr_channel_monthly_capacity_ctrl m
WHERE m.is_deleted = 0
AND DATE_FORMAT(m.stat_month, '%Y-%m') <= #{statMonth}


        AND m.channel = #{channel}


        AND m.channel ='全部'




        AND m.big_category = #{bigCategory}


        AND m.big_category ='全部'




        AND m.small_category = #{smallCategory}


        AND m.small_category ='全部'



    AND m.city_id = #{cityId}


    AND m.county_id = #{countyId}

ORDER BY m.stat_month DESC
LIMIT 6

choose.otherwise:
SELECT m.stat_month AS month,
       m.capacity   AS capacity,
       m.qoq        AS qoq
FROM t_sr_channel_monthly_capacity_ap m
WHERE m.tab_type = #{tabType}
  AND m.is_deleted = 0

    AND m.strategy_class = #{strategyClass}

    AND m.strategy_class = '全部'

AND DATE_FORMAT(m.stat_month, '%Y-%m') <= #{statMonth}


        AND m.channel = #{channel}


        AND m.channel ='全部'




        AND m.big_category = #{bigCategory}


        AND m.big_category ='全部'




        AND m.small_category = #{smallCategory}


        AND m.small_category ='全部'



    AND m.city_id = #{cityId}


    AND m.county_id = #{countyId}

ORDER BY m.stat_month DESC
LIMIT 6

choose.when:
SELECT b.big_category   AS bigCategory,
       b.small_category AS smallCategory,
       b.biz_name       AS bizName,
       b.capacity       AS capacity,
       b.qoq            AS qoq
FROM t_sr_channel_biz_capacity_ctrl b
WHERE DATE_FORMAT(b.stat_month, '%Y-%m') = #{statMonth}
  AND b.is_deleted = 0
  AND b.biz_name != '全部'

and b.channel!='全部' and b.big_category !='全部' and b.small_category !='全部' and b.biz_name!='全部'


    AND b.channel = #{channel}


    AND b.big_category = #{bigCategory}


    AND b.small_category = #{smallCategory}


    AND b.city_id = #{cityId}


    AND b.county_id = #{countyId}

ORDER BY b.capacity DESC

choose.otherwise:
SELECT b.big_category   AS bigCategory,
       b.small_category AS smallCategory,
       b.biz_name       AS bizName,
       b.capacity       AS capacity,
       b.qoq            AS qoq
FROM t_sr_channel_biz_capacity_ap b
WHERE b.tab_type = #{tabType}
  AND DATE_FORMAT(b.stat_month, '%Y-%m') = #{statMonth}
  AND b.is_deleted = 0

      AND b.strategy_class = #{strategyClass}

      AND b.strategy_class = '全部'

  AND b.biz_name != '全部'

  and b.channel!='全部' and b.big_category !='全部' and b.small_category !='全部' and b.biz_name!='全部'


    AND b.channel = #{channel}


    AND b.big_category = #{bigCategory}


    AND b.small_category = #{smallCategory}


    AND b.city_id = #{cityId}


    AND b.county_id = #{countyId}

ORDER BY b.capacity DESC

choose.when:
SELECT s.big_category AS bigCategory, s.strategy_code AS strategyCode, s.channel AS channel, s.big_category AS bigCategory, s.strategy_count AS strategyCount, s.small_category AS smallCategory, s.consult_count AS consultCount, s.consult_count_qoq AS consultCountQoQ, s.retain_count AS retainCount, s.retain_count_qoq AS retainCountQoQ, s.retain_rate AS retainRate, s.retain_rate_qoq AS retainRateQoQ, s.dispatch_count AS dispatchCount, s.dispatch_count_qoq AS dispatchCountQoQ, s.success_count AS successCount, s.success_count_qoq AS successCountQoQ, s.success_rate AS successRate, s.success_rate_qoq AS successRateQoQ, s.income AS income, s.income_qoq AS incomeQoQ FROM t_sr_strategy_period_summary_ctrl s WHERE DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth} AND s.is_deleted = 0 and s.strategy_id = '999' and s.big_category !='全部' and s.small_category !='全部'
and s.channel!='全部'
AND s.city_id = #{cityId}
AND s.county_id = #{countyId}
AND s.channel = #{channel}
AND s.big_category = #{bigCategory}
AND s.small_category = #{smallCategory}
ORDER BY strategyCount DESC

choose.otherwise:
SELECT s.big_category AS bigCategory, s.strategy_name AS strategyName, s.channel AS channel, s.big_category AS bigCategory, s.small_category AS smallCategory, s.strategy_count AS strategyCount, s.original_cust AS originalCust, s.original_cust_qoq AS originalCustQoQ, s.push_count AS pushCount, s.push_count_qoq AS pushCountQoQ, s.usage_count AS usageCount, s.usage_count_qoq AS usageCountQoQ, s.usage_rate AS usageRate, s.usage_rate_qoq AS usageRateQoQ, s.reach_count AS reachCount, s.reach_count_qoq AS reachCountQoQ, s.target_conv_num AS targetConvNum, s.target_conv_num_qoq AS targetConvNumQoQ, s.target_conv_rate AS targetConvRate, s.target_conv_rate_qoq AS targetConvRateQoQ, s.product_conv_num AS productConvNum, s.product_conv_num_qoq AS productConvNumQoQ, s.product_conv_rate AS productConvRate, s.product_conv_rate_qoq AS productConvRateQoQ, s.expected_income AS expectedIncome, s.expected_income_qoq AS expectedIncomeQoQ, s.actual_income AS actualIncome, s.actual_income_qoq AS actualIncomeQoQ, s.reject_rate AS rejectRate, s.reject_rate_qoq AS rejectRateQoQ, s.reject_count AS rejectCount FROM t_sr_strategy_period_summary_ap s WHERE s.tab_type = #{tabType} AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth} AND s.is_deleted = 0 and 0=#{queryList} and s.strategy_id = '999'
AND s.strategy_class = #{strategyClass}
AND s.strategy_class = '全部'
and s.big_category !='全部' and s.small_category !='全部'
and s.channel!='全部'
AND s.city_id = #{cityId}
AND s.county_id = #{countyId}
AND s.channel = #{channel}
AND s.big_category = #{bigCategory}
AND s.small_category = #{smallCategory}
ORDER BY strategyCount DESC

choose.when:
SELECT DATE_FORMAT(s.stat_month, '%Y-%m') AS month, s.success_count AS capacity, s.success_count_qoq AS qoq, ${metricColumn} AS metricValue FROM t_sr_strategy_period_summary_ctrl s WHERE s.strategy_id = #{strategyId} AND s.is_deleted = 0 AND DATE_FORMAT(s.stat_month, '%Y-%m') <= #{statMonth} and s.channel!='全部' and s.big_category !='全部' and s.small_category !='全部'
AND s.city_id = #{cityId}
AND s.county_id = #{countyId}
ORDER BY s.stat_month DESC LIMIT 6

choose.otherwise:
SELECT DATE_FORMAT(s.stat_month, '%Y-%m') AS month, s.product_conv_num AS capacity, s.product_conv_num_qoq AS qoq, ${metricColumn} AS metricValue FROM t_sr_strategy_period_summary_ap s WHERE s.strategy_id = #{strategyId} AND (s.tab_type = #{tabType} OR s.tab_type IS NULL) AND s.is_deleted = 0 AND DATE_FORMAT(s.stat_month, '%Y-%m') <= #{statMonth} and s.channel!='全部' and s.big_category !='全部' and s.small_category !='全部'
AND s.city_id = #{cityId}
AND s.county_id = #{countyId}
ORDER BY s.stat_month DESC LIMIT 6

mapper.select:
SELECT b.biz_code  AS bizCode,
       b.biz_name  AS bizName,
       b.count     AS count,
       b.mom_ratio AS momRatio,
       b.yoy_ratio AS yoyRatio
FROM t_sr_strategy_biz_capacity b
WHERE b.tab_type = #{tabType}
  AND b.strategy_id = #{strategyId}
  AND b.stat_date >= STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d')
  AND b.stat_date < DATE_ADD(STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
  AND b.is_deleted = 0  and b.biz_name!='全部'

    AND b.city_id = #{cityId}


    AND b.county_id = #{countyId}

ORDER BY b.count DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM t_sr_strategy_biz_capacity b
WHERE b.tab_type = #{tabType}
  AND b.strategy_id = #{strategyId}
  AND b.stat_date >= STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d')
  AND b.stat_date < DATE_ADD(STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
  AND b.is_deleted = 0 and  b.biz_name!='全部'

    AND b.city_id = #{cityId}


    AND b.county_id = #{countyId}

choose.when:
SELECT DATE_FORMAT(d.stat_date, '%Y-%m-%d') AS date, d.big_category AS bigCategory, d.small_category AS smallCategory, d.strategy_name AS strategyName, d.strategy_name AS name, d.consult_count AS consultCount, d.retain_count AS retainCount, d.retain_rate AS retainRate, d.dispatch_count AS dispatchCount, d.success_count AS successCount, d.success_rate AS successRate FROM t_sr_strategy_daily_ctrl d WHERE d.strategy_id = #{strategyId} AND d.is_deleted = 0 and d.channel!='全部' and d.big_category !='全部' and d.small_category !='全部' and d.strategy_name!='全部'
AND d.city_id = #{cityId}
AND d.county_id = #{countyId}
AND d.stat_date >= #{startDate}
AND d.stat_date <= #{endDate}
ORDER BY d.stat_date DESC LIMIT #{limit} OFFSET #{offset}

choose.otherwise:
SELECT DATE_FORMAT(d.stat_date, '%Y-%m-%d') AS date, d.original_cust AS originalCust, d.push_count AS pushCount, d.strategy_class AS strategyClass, d.big_category AS bigCategory, d.small_category AS smallCategory, d.strategy_name AS strategyName, d.strategy_name AS name, d.usage_count AS usageCount, d.usage_rate AS usageRate, d.reach_count AS reachCount, d.target_conv_num AS targetConvNum, d.target_conv_rate AS targetConvRate, d.product_conv_num AS productConvNum, d.product_conv_rate AS productConvRate, d.expected_income AS expectedIncome, d.actual_income AS actualIncome, d.reject_count AS rejectCount, d.reject_rate AS rejectRate FROM t_sr_strategy_daily_ap d WHERE d.strategy_id = #{strategyId} AND (d.tab_type = #{tabType} OR d.tab_type IS NULL) AND d.is_deleted = 0 and d.channel!='全部' and d.big_category !='全部' and d.small_category !='全部' and d.strategy_name!='全部'
AND d.city_id = #{cityId}
AND d.county_id = #{countyId}
AND d.stat_date >= #{startDate}
AND d.stat_date <= #{endDate}
ORDER BY d.stat_date DESC LIMIT #{limit} OFFSET #{offset}

choose.when:
SELECT COUNT(1)
FROM t_sr_strategy_daily_ctrl d
WHERE d.strategy_id = #{strategyId}
  AND d.is_deleted = 0
and d.channel!='全部' and d.big_category !='全部' and d.small_category !='全部' and d.strategy_name!='全部'

    AND d.city_id = #{cityId}


    AND d.county_id = #{countyId}


    AND d.stat_date >= #{startDate}


    AND d.stat_date <= #{endDate}

choose.otherwise:
SELECT COUNT(1)
FROM t_sr_strategy_daily_ap d
WHERE d.strategy_id = #{strategyId}
  AND (d.tab_type = #{tabType} OR d.tab_type IS NULL)
  AND d.is_deleted = 0
and d.channel!='全部' and d.big_category !='全部' and d.small_category !='全部' and d.strategy_name!='全部'

    AND d.city_id = #{cityId}


    AND d.county_id = #{countyId}


    AND d.stat_date >= #{startDate}


    AND d.stat_date <= #{endDate}

mapper.select:
SELECT reject_rate AS rejectRate, reject_rate_qoq AS rejectRateQoQ, reject_count AS rejectCount
FROM t_sr_strategy_period_summary_ap
WHERE strategy_id = #{strategyId}
  AND DATE_FORMAT(stat_month, '%Y-%m') = #{statMonth}
  AND is_deleted = 0

    AND city_id = #{cityId}


    AND county_id = #{countyId}

LIMIT 1

SELECT r.reason_code   AS reasonCode,
       r.reason_name   AS reasonName,
       r.reject_count  AS rejectCount,
       r.reject_ratio  AS ratio,
       r.color         AS color
FROM t_sr_strategy_reject_reason r
WHERE r.strategy_id = #{strategyId}
  AND DATE_FORMAT(r.stat_month, '%Y-%m') = #{statMonth}
  AND r.is_deleted = 0

    AND r.city_id = #{cityId}


    AND r.county_id = #{countyId}

ORDER BY r.sort_no, r.reject_count DESC
